import{_ as r,o,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const h=JSON.parse('{"title":"08.4 课后考题","description":"","frontmatter":{},"headers":[],"relativePath":"08-信息安全/90-课后考题.md","filePath":"08-信息安全/90-课后考题.md"}'),a={name:"08-信息安全/90-课后考题.md"};function e(p,t,g,_,i,l){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_08-4-课后考题" tabindex="-1">08.4 课后考题 <a class="header-anchor" href="#_08-4-课后考题" aria-label="Permalink to &quot;08.4 课后考题&quot;">​</a></h1><h3 id="选择题" tabindex="-1">选择题 <a class="header-anchor" href="#选择题" aria-label="Permalink to &quot;选择题&quot;">​</a></h3><p><strong>1.</strong> 某网站数据库被攻击者篡改了首页内容，这直接破坏了信息安全五大属性中的（）。 A. 机密性 B. 完整性 C. 可用性 D. 不可否认性</p><p><strong>2.</strong> 下列攻击中，属于被动攻击的是（）。 A. 流量分析 B. 重放攻击 C. 拒绝服务攻击 D. 信息篡改</p><p><strong>3.</strong> DES 加密算法属于（）。 A. 非对称加密算法 B. 对称加密算法 C. 信息摘要算法 D. 数字签名算法</p><p><strong>4.</strong> 关于对称加密与非对称加密，下列叙述正确的是（）。 A. 非对称加密的加解密速度通常比对称加密快 B. 对称加密中，加密密钥与解密密钥必须不同 C. 非对称加密体制中，公钥可以公开，私钥由本人秘密保存 D. RSA 算法适合对大文件进行快速加密</p><p><strong>5.</strong> 某系统有 10 个用户，任意两个用户之间都需要用对称加密秘密通信。若每对用户共用一把密钥，则全系统共需（）把密钥。 A. 10 B. 20 C. 45 D. 90</p><p><strong>6.</strong> 甲要给乙发送大量机密数据，采用数字信封（混合加密）方式。正确的做法是（）。 A. 甲用乙的公钥加密全部数据，用对称密钥加密乙的私钥 B. 甲生成对称密钥加密数据，再用乙的公钥加密该对称密钥后一起发送 C. 甲用自己的私钥加密数据，用对称密钥加密自己的公钥 D. 甲用乙的私钥加密数据，用对称密钥加密自己的私钥</p><p><strong>7.</strong> 信息摘要（Hash）算法不具备的特性是（）。 A. 对任意长度的输入产生固定长度的输出 B. 由摘要无法反向推出原文 C. 使用密钥参与运算，不同密钥产生不同摘要 D. 原文微小改动会导致摘要发生巨大变化</p><p><strong>8.</strong> MD5 算法产生的信息摘要长度是（）位。 A. 64 B. 128 C. 160 D. 256</p><p><strong>9.</strong> 甲向乙发送了附有数字签名的消息，乙收到后应使用（）验证该签名。 A. 甲的公钥 B. 甲的私钥 C. 乙的公钥 D. 乙的私钥</p><p><strong>10.</strong> 数字签名技术不能提供的保障是（）。 A. 证明消息确实由签名者发出 B. 签名者无法否认发过该消息 C. 发现消息在传输中是否被篡改 D. 防止消息的内容被第三方窃听</p><p><strong>11.</strong> 甲要与乙通信，既要保证消息机密性，又要让乙能验证消息确实出自甲且未被篡改。正确的流程是（）。 A. 甲用自己的公钥签名摘要，用甲的私钥加密消息后发送 B. 甲用甲的私钥对摘要签名，再将消息和签名用乙的公钥加密后发送 C. 甲用乙的公钥对摘要签名，再用甲的公钥加密消息后发送 D. 甲先用乙的私钥加密消息，再用自己的公钥对全文签名</p><p><strong>12.</strong> 关于数字证书，下列叙述正确的是（）。 A. 数字证书中包含证书持有者的公钥 B. 验证数字证书的有效性应使用证书持有者的公钥 C. 数字证书由证书持有者自己生成并签名 D. 数字证书中包含证书持有者的私钥</p><p><strong>13.</strong> 包过滤防火墙工作在（），根据数据包的源地址、目的地址和端口号决定放行或丢弃。 A. 应用层 B. 会话层 C. 网络层 D. 物理层</p><p><strong>14.</strong> 关于防火墙，下列叙述中不正确的是（）。 A. 可以控制进出网络的数据包和数据流向 B. 可以提供网络流量信息的日志和审计 C. 可以有效防范来自网络内部人员的攻击 D. 可以隐藏内部网络的 IP 地址和结构细节</p><p><strong>15.</strong> 攻击者截获某用户登录系统时的合法认证报文，稍后将其原样发给服务器冒充该用户登录。这种攻击属于（）。 A. 重放攻击 B. SQL 注入攻击 C. 分布式拒绝服务攻击 D. 钓鱼攻击</p><h3 id="案例题风格题" tabindex="-1">案例题风格题 <a class="header-anchor" href="#案例题风格题" aria-label="Permalink to &quot;案例题风格题&quot;">​</a></h3><p><strong>16.</strong> 某银行系统要求客户甲向服务器乙提交转账指令时，满足：① 只有乙能读取指令内容；② 乙能确认指令确实由甲发出且未被篡改。系统采用公钥密码体制（每人一对公私钥）和 Hash 函数。</p><p>（1）甲对指令正文生成信息摘要，应使用什么函数？ （2）甲对摘要进行签名，应使用谁的什么密钥？ （3）将&quot;指令+签名&quot;加密后发送，应使用谁的什么密钥？ （4）乙收到后先做什么才能读到指令内容？随后用什么密钥验证签名？ （5）若攻击者 P 截获了甲此前提交的一条合法指令报文，并于次日原样重发给乙。这种攻击叫什么？系统可采用什么机制防住它？</p><hr>',21)])])}const c=r(a,[["render",e]]);export{h as __pageData,c as default};
